package school.magiccodex.party;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import java.sql.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class KyudichiNamesTest {
 @TempDir Path temp;
 @Test void offlineSharedLookupUsesOriginalNicknameAndPendingFallbackWithoutChangingRows()throws Exception{
  UUID id=UUID.randomUUID(),blank=UUID.randomUUID();try(var c=DriverManager.getConnection("jdbc:h2:mem:"+UUID.randomUUID())){try(var s=c.createStatement()){s.execute("CREATE TABLE nicknames(owner VARCHAR(36) PRIMARY KEY,account VARCHAR(16),nickname VARCHAR(16))");}try(var s=c.prepareStatement("INSERT INTO nicknames VALUES(?,?,?)")){s.setString(1,id.toString());s.setString(2,"Zzunwoo");s.setString(3,"황준우");s.executeUpdate();s.setString(1,blank.toString());s.setString(2,"NoNickname");s.setString(3,"");s.executeUpdate();}
   assertEquals("황준우",KyudichiNames.display(c,"nicknames",id,"OldAccount"));assertEquals("닉네임 확인 중",KyudichiNames.display(c,"nicknames",blank,"닉네임 확인 중"));assertEquals("OldAccount",KyudichiNames.display(c,"nicknames",UUID.randomUUID(),"OldAccount"));assertEquals(id,KyudichiNames.find(c,"nicknames","황준우",false));assertEquals(id,KyudichiNames.find(c,"nicknames","Zzunwoo",false));try(var s=c.createStatement()){s.executeUpdate("UPDATE nicknames SET nickname='새이름' WHERE account='Zzunwoo'");}assertEquals("새이름",KyudichiNames.display(c,"nicknames",id,"old"));try(var s=c.createStatement();var rs=s.executeQuery("SELECT COUNT(*) FROM nicknames")){assertTrue(rs.next());assertEquals(2,rs.getInt(1));}}
 }
 @Test void trustedNameCacheSurvivesRestartRenamesAndDoesNotInventUnknownNames()throws Exception{UUID id=UUID.randomUUID();Path f=temp.resolve("ranking-display-names.properties");var cache=new RankingNameCache(f);assertEquals("Account",cache.name(id,"Account"));cache.remember(id,"황준우");assertEquals("황준우",new RankingNameCache(f).name(id,"Account"));cache.remember(id,"새이름");assertEquals("새이름",new RankingNameCache(f).name(id,"Account"));assertThrows(IllegalArgumentException.class,()->cache.remember(id,"bad\nname"));assertEquals("새이름",new RankingNameCache(f).name(id,"Account"));}
 @Test void unreadableCacheIsPreservedInsteadOfOverwritten()throws Exception{Path f=temp.resolve("bad.properties");Files.writeString(f,"bad-key=nickname");assertThrows(java.io.IOException.class,()->new RankingNameCache(f));assertEquals("bad-key=nickname",Files.readString(f));}
}
